<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS client (id_client INT AUTO_INCREMENT PRIMARY KEY,code_client VARCHAR(80),nom_client VARCHAR(190) NOT NULL,localisation_client VARCHAR(190),commune_client VARCHAR(120),bp_client VARCHAR(80),pays_client VARCHAR(120),date_creat_client DATE,logo_client VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
